import { Box, Button, Typography } from "@mui/material";
import type { HomeCta } from "../types/home";

const LIVE_SITE = "https://www.doctutorials.com";

function livePageUrl(url?: string) {
  if (!url) return "";
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith("/")) return `${LIVE_SITE}${url}`;
  return `${LIVE_SITE}/${url}`;
}

export default function ExamCta({ data }: { data?: HomeCta | null }) {
  if (!data?.title && !data?.buttonUrl) return null;
  const buttonUrl = livePageUrl(data.buttonUrl);

  return (
    <Box sx={{ textAlign: "center", px: { xs: 2, sm: 3, tv: 6 }, py: { xs: 4, sm: 5, md: 6, tv: 8 } }}>
      {data.title ? (
        <Typography
          sx={{
            color: "#17224d",
            fontSize: { xs: 22, sm: 26, md: 32, lg: 36, tv: 44 },
            fontWeight: 600,
            mb: { xs: 2, md: 3 },
            px: 1,
          }}
        >
          {data.title}
        </Typography>
      ) : null}
      {data.buttonUrl ? (
        <Button
          variant="contained"
          href={data.buttonUrl}
          target="_blank"
          rel="noopener noreferrer"
          sx={{
            backgroundColor: "#759ae1",
            px: { xs: 3, md: 4, tv: 5 },
            py: { xs: 1, md: 1.2 },
            fontSize: { xs: 14, md: 16, tv: 18 },
            borderRadius: "6px",
            "&:hover": { backgroundColor: "#5f86d4" },
          }}
        >
          {data.buttonLabel || "Subscribe Now"}
        </Button>
      ) : null}
    </Box>
  );
}
